\echo === 11. pipeline: stage gates, history, optimistic concurrency
do $$ declare l uuid; v int; lost uuid; begin
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  insert into public.leads (company_name, contact_name, email, owner_id, service_id, estimated_value)
  values ('Acme Ltd','Jo Acme','jo@acme.test','00000000-0000-0000-0000-0000000000e1',(select id from public.services order by position limit 1), 50000) returning id into l;
  perform t.eq(t.val(format($q$select lead_number ~ '^LD-\d{6}$' from public.leads where id=%L$q$, l)), 'true', 'lead number generated by DB (LD-000000 format)');
  perform t.eq(t.val(format($q$select stage from public.leads where id=%L$q$, l)), 'new', 'new leads start in the New stage');
  perform t.eq(t.val(format($q$select created_by::text from public.leads where id=%L$q$, l)), '00000000-0000-0000-0000-0000000000e1', 'created_by stamped from trusted identity');
  perform t.eq(t.val(format($q$select count(*) from public.lead_stage_history where lead_id=%L$q$, l)), '1', 'creation recorded in stage history');
  perform t.eq(t.val(format($q$select count(*) from public.lead_assignments where lead_id=%L and unassigned_at is null$q$, l)), '1', 'initial assignment recorded');

  perform t.denied(format($q$select public.move_lead_stage(%L,'qualified')$q$, l), 'qualification gate blocks incomplete lead');
  update public.leads set decision_maker = 'Raj', website = 'https://acme.test' where id = l;     -- 15+20+10+15+10 = 70
  perform t.eq(t.val(format($q$select (public.lead_qualification(%L)->>'score')$q$, l)), '70', 'qualification score is transparent');
  select row_version into v from public.leads where id = l;
  perform t.denied(format($q$select public.move_lead_stage(%L,'qualified',null,null,%s)$q$, l, v + 5), 'stale row_version rejected (optimistic concurrency)', array['40001']);
  perform public.move_lead_stage(l, 'qualified', 'ready', null, v);
  perform t.eq(t.val(format($q$select stage from public.leads where id=%L$q$, l)), 'qualified', 'stage moved via RPC');
  perform t.eq(t.val(format($q$select count(*) from public.lead_stage_history where lead_id=%L$q$, l)), '2', 'stage change recorded in history');
  perform t.eq(t.val(format($q$select count(*) from public.activities where lead_id=%L and activity_type='stage_change'$q$, l)), '1', 'stage change recorded as activity');
  perform public.move_lead_stage(l, 'qualified');                                                      -- idempotent no-op
  perform t.eq(t.val(format($q$select count(*) from public.lead_stage_history where lead_id=%L$q$, l)), '2', 'repeating the same move adds no history');
  perform t.denied(format($q$select public.move_lead_stage(%L,'won')$q$, l), 'Won only via conversion workflow');
  perform t.denied(format($q$select public.move_lead_stage(%L,'lost')$q$, l), 'Lost requires a reason');
  perform t.denied(format($q$select public.move_lead_stage(%L,'no_such_stage')$q$, l), 'unknown stage rejected');
  select id into lost from public.lost_reasons limit 1;
  perform public.move_lead_stage(l, 'lost', 'went quiet', lost);
  perform t.eq(t.val(format($q$select lost_reason_id is not null from public.leads where id=%L$q$, l)), 'true', 'lost reason stored');
  perform t.denied(format($q$select public.move_lead_stage(%L,'new')$q$, l), 'employee cannot reopen a lost lead');
  perform t.denied(format($q$select public.convert_lead_to_client(%L)$q$, l), 'lost lead cannot be converted');
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  perform public.move_lead_stage(l, 'contacted', 'reopened by mentor');
  perform t.eq(t.val(format($q$select stage || ':' || coalesce(lost_reason_id::text,'none') from public.leads where id=%L$q$, l)), 'contacted:none', 'mentor reopens lost lead, reason cleared');
  perform t.act('00000000-0000-0000-0000-0000000000e2');
  perform t.denied(format($q$select public.move_lead_stage(%L,'interested')$q$, l), 'other employee cannot move this lead');
  perform t.denied(format($q$select public.move_lead_stage('10000000-0000-0000-0000-000000000001','interested',null,null)$q$), 'E2 cannot move E1 lead (assigned back to E1)');
end $$;

\echo === 12. activities keep the lead current; duplicate submissions are idempotent
do $$ declare l uuid; rid uuid := gen_random_uuid(); begin
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  l := '10000000-0000-0000-0000-000000000001';
  insert into public.activities (request_id, lead_id, user_id, activity_type, subject, next_follow_up_at)
    values (rid, l, '00000000-0000-0000-0000-0000000000e1', 'call', 'Intro call', now() + interval '3 days');
  perform t.eq(t.val(format($q$select (last_contacted_at is not null and next_follow_up_at > now())::text from public.leads where id=%L$q$, l)), 'true', 'call updates last-contacted and next follow-up');
  perform t.denied(format($q$insert into public.activities (request_id, lead_id, user_id, activity_type) values (%L,%L,'00000000-0000-0000-0000-0000000000e1','call')$q$, rid, l), 'double-submit (same request_id) rejected');
  perform t.denied($q$insert into public.activities (user_id, activity_type) values ('00000000-0000-0000-0000-0000000000e1','call')$q$, 'activity must reference a lead or client', array['23514']);
  perform t.affects($q$delete from public.activities$q$, 0, 'employees cannot delete activities (0 rows)');
end $$;

\echo === 13. conversion: atomic, idempotent, scoped
do $$ declare l uuid; r jsonb; r2 jsonb; c0 bigint; begin
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  insert into public.leads (company_name, contact_name, email, owner_id, service_id, estimated_value)
  values ('Beta Corp','Bea','bea@beta.test','00000000-0000-0000-0000-0000000000e1',(select id from public.services order by position limit 1), 80000) returning id into l;
  perform t.denied(format($q$select public.convert_lead_to_client(%L, 0)$q$, l), 'zero deal value rejected');
  -- failure AFTER the client row is inserted (project dates invalid) must roll the whole conversion back
  select count(*) into c0 from public.clients where company_name = 'Beta Corp';
  perform t.denied(format($q$select public.convert_lead_to_client(%L, 80000, null, null, null, null, null, null, date '2026-12-31', date '2026-01-01')$q$, l), 'invalid project dates abort conversion');
  perform t.eq(t.val($q$select count(*) from public.clients where company_name = 'Beta Corp'$q$), c0::text, 'rollback: no orphan client created');
  perform t.eq(t.val(format($q$select stage from public.leads where id=%L$q$, l)), 'new', 'rollback: lead untouched');
  perform t.eq(t.val(format($q$select count(*) from public.lead_stage_history where lead_id=%L$q$, l)), '1', 'rollback: no stray history');

  r := public.convert_lead_to_client(l, 90000, 'Beta Website', null, 'Marketing site', 'Net 15', 'Launch by Q1', 'Kickoff call', current_date, current_date + 60);
  perform t.eq(r->>'already_converted', 'false', 'first conversion performs work');
  r2 := public.convert_lead_to_client(l, 90000);
  perform t.eq(r2->>'already_converted', 'true', 'second conversion is an idempotent replay');
  perform t.eq(r2->>'client_id', r->>'client_id', 'replay returns the same client');
  perform t.eq(t.val($q$select count(*) from public.clients where company_name = 'Beta Corp'$q$), '1', 'exactly one client exists');
  perform t.eq(t.val(format($q$select count(*) from public.projects where client_id = %L$q$, r->>'client_id')), '1', 'exactly one project exists');
  perform t.eq(t.val(format($q$select stage || ':' || (converted_client_id is not null)::text || ':' || coalesce(probability,0) from public.leads where id=%L$q$, l)), 'won:true:100', 'lead marked Won and linked');
  perform t.eq(t.val(format($q$select count(*) from public.activities where lead_id=%L and activity_type='conversion'$q$, l)), '1', 'conversion activity recorded once');
  perform t.eq(t.val(format($q$select agreed_value::text from public.projects where client_id=%L$q$, r->>'client_id')), '90000.00', 'project carries agreed value');
  perform t.eq(t.val(format($q$select public.client_handover(%L)->'projects'->0->>'payment_terms'$q$, r->>'client_id')), 'Net 15', 'handover includes payment terms');
  perform t.eq(t.val(format($q$select public.client_handover(%L)->>'relationship_owner'$q$, r->>'client_id')), 'Eve Renamed', 'handover names relationship owner');
  -- owner gets read-only handover access
  perform t.eq(t.val($q$select count(*) from public.clients where company_name='Beta Corp'$q$), '1', 'owner can read own client');
  perform t.affects($q$update public.clients set company_name = 'Hacked' where company_name='Beta Corp'$q$, 0, 'owner cannot edit client');
  perform t.affects($q$update public.projects set agreed_value = 1$q$, 0, 'owner cannot edit project value');
  perform t.denied(format($q$select public.move_lead_stage(%L,'new')$q$, l), 'converted lead cannot be moved');
  perform t.affects(format($q$delete from public.clients where id=%L$q$, r->>'client_id'), 0, 'owner cannot delete client (0 rows)');
  -- others
  perform t.act('00000000-0000-0000-0000-0000000000e2');
  perform t.eq(t.val($q$select count(*) from public.clients where company_name='Beta Corp'$q$), '0', 'other employee cannot see client');
  perform t.denied(format($q$select public.convert_lead_to_client(%L)$q$, l), 'other employee cannot convert');
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  perform t.eq(t.val($q$select count(*) from public.clients where company_name='Beta Corp'$q$), '1', 'owner''s mentor sees the client');
  perform t.act('00000000-0000-0000-0000-0000000000b2');
  perform t.eq(t.val($q$select count(*) from public.clients where company_name='Beta Corp'$q$), '0', 'unrelated mentor cannot see client');
  perform t.act('00000000-0000-0000-0000-0000000000a1');
  perform t.denied(format($q$insert into public.clients (company_name, source_lead_id) values ('Dupe', %L)$q$, l), 'unique(source_lead_id) blocks a second client per lead');
end $$;

\echo === 14. tasks
do $$ declare tk uuid; rid uuid := gen_random_uuid(); begin
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.denied($q$insert into public.tasks (title, assigned_to) values ('for E2','00000000-0000-0000-0000-0000000000e2')$q$, 'employee cannot assign tasks to others');
  insert into public.tasks (request_id, title, assigned_to) values (rid, 'Follow up', '00000000-0000-0000-0000-0000000000e1') returning id into tk;
  perform t.denied(format($q$insert into public.tasks (request_id, title, assigned_to) values (%L,'Follow up','00000000-0000-0000-0000-0000000000e1')$q$, rid), 'retry with same request_id creates no duplicate task');
  perform t.denied(format($q$update public.tasks set assigned_to='00000000-0000-0000-0000-0000000000e2' where id=%L$q$, tk), 'employee cannot reassign task');
  perform t.denied(format($q$update public.tasks set completed_at=now() where id=%L$q$, tk), 'completed_at is system-controlled');
  update public.tasks set status = 'completed' where id = tk;
  perform t.eq(t.val(format($q$select (completed_at is not null)::text from public.tasks where id=%L$q$, tk)), 'true', 'completing a task stamps completed_at');
  update public.tasks set status = 'in_progress' where id = tk;
  perform t.eq(t.val(format($q$select (completed_at is null)::text from public.tasks where id=%L$q$, tk)), 'true', 'reopening clears completed_at');
  insert into public.task_comments (task_id, author_id, content) values (tk, '00000000-0000-0000-0000-0000000000e1', 'on it');
  perform t.denied(format($q$insert into public.task_comments (task_id, author_id, content) values (%L,'00000000-0000-0000-0000-0000000000e1','x')$q$, '20000000-0000-0000-0000-000000000003'), 'cannot comment on invisible task');
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  insert into public.tasks (title, assigned_to, priority) values ('Mentor assigned','00000000-0000-0000-0000-0000000000e2','high');
  perform t.act('00000000-0000-0000-0000-0000000000e2');
  perform t.eq(t.val($q$select count(*) from public.notifications where type='task_assigned'$q$), '1', 'assignee notified');
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.eq(t.val($q$select count(*) from public.notifications where recipient_id <> '00000000-0000-0000-0000-0000000000e1'$q$), '0', 'notifications are private to the recipient');
  perform t.eq(t.val($q$select count(*) from public.notifications where type = 'task_assigned'$q$), '0', 'E1 does not see the task notification meant for E2');
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  perform t.eq(t.val(format($q$select count(*) from public.tasks where id=%L$q$, tk)), '1', 'mentor sees team task');
  perform t.act('00000000-0000-0000-0000-0000000000b2');
  perform t.eq(t.val(format($q$select count(*) from public.tasks where id=%L$q$, tk)), '0', 'other mentor does not');
end $$;

\echo === 15. daily reports derive metrics from source data
do $$ declare rid uuid; begin
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.denied($q$insert into public.daily_reports (user_id, report_date, leads_created) values ('00000000-0000-0000-0000-0000000000e1', current_date, 99)$q$, 'client cannot submit self-reported metrics');
  insert into public.daily_reports (user_id, report_date, summary) values ('00000000-0000-0000-0000-0000000000e1', current_date, 'busy day') returning id into rid;
  perform t.eq(t.val(format($q$select (leads_created >= 2 and outreach_completed >= 1)::text from public.daily_reports where id=%L$q$, rid)), 'true', 'metrics derived from leads/activities');
  perform t.eq(t.val(format($q$select leads_created::text from public.daily_reports where id=%L$q$, rid)), t.val($q$select count(*)::text from public.leads where created_by='00000000-0000-0000-0000-0000000000e1' and created_at::date=current_date$q$), 'derived count matches source rows');
  perform t.denied($q$insert into public.daily_reports (user_id, report_date) values ('00000000-0000-0000-0000-0000000000e1', current_date)$q$, 'one report per user per day');
  perform t.denied($q$insert into public.daily_reports (user_id, report_date) values ('00000000-0000-0000-0000-0000000000e2', current_date)$q$, 'cannot file a report for someone else');
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  perform t.eq(t.val('select count(*) from public.daily_reports'), '1', 'mentor reads team reports');
  perform t.act('00000000-0000-0000-0000-0000000000b2');
  perform t.eq(t.val('select count(*) from public.daily_reports'), '0', 'other mentor cannot');
end $$;

\echo === 16. coaching notes, approvals, escalations
do $$ declare ar uuid; ar2 uuid; ar3 uuid; ld uuid := '10000000-0000-0000-0000-000000000002'; begin
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  insert into public.coaching_notes (employee_id, mentor_id, note) values ('00000000-0000-0000-0000-0000000000e1','00000000-0000-0000-0000-0000000000b1','Work on discovery questions');
  perform t.denied($q$insert into public.coaching_notes (employee_id, mentor_id, note) values ('00000000-0000-0000-0000-0000000000e3','00000000-0000-0000-0000-0000000000b1','nope')$q$, 'mentor cannot coach outside team');
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.eq(t.val('select count(*) from public.coaching_notes'), '1', 'employee reads own coaching notes');
  perform t.denied($q$insert into public.coaching_notes (employee_id, mentor_id, note) values ('00000000-0000-0000-0000-0000000000e1','00000000-0000-0000-0000-0000000000e1','self')$q$, 'employee cannot author coaching notes');
  insert into public.approval_requests (request_type, requested_by, reason) values ('mentor_support','00000000-0000-0000-0000-0000000000e1','Need help with pricing') returning id into ar;
  insert into public.approval_requests (request_type, requested_by, reason) values ('discount_exception','00000000-0000-0000-0000-0000000000e1','20% off') returning id into ar2;
  perform t.denied($q$insert into public.approval_requests (request_type, requested_by) values ('mentor_support','00000000-0000-0000-0000-0000000000e2')$q$, 'cannot file a request as someone else');
  perform t.denied(format($q$update public.approval_requests set status='approved' where id=%L$q$, ar), 'requester cannot self-approve');
  perform t.denied(format($q$select public.decide_approval(%L, true)$q$, ar), 'requester cannot call decide_approval');
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  perform t.eq(t.val($q$select count(*) from public.notifications where type='approval_requested'$q$), '2', 'mentor notified of requests');
  perform public.decide_approval(ar, true, 'Let''s pair tomorrow');
  perform t.denied(format($q$select public.decide_approval(%L, true)$q$, ar2), 'mentor cannot decide a discount exception');
  perform t.denied(format($q$select public.decide_approval(%L, false)$q$, ar), 'decided requests cannot be re-decided');
  perform t.act('00000000-0000-0000-0000-0000000000b2');
  perform t.eq(t.val('select count(*) from public.approval_requests'), '0', 'other mentor cannot see requests');
  perform t.act('00000000-0000-0000-0000-0000000000a1');
  perform public.decide_approval(ar2, false, 'no');
  insert into public.approval_requests (request_type, entity_type, entity_id, requested_by, reason)
    values ('deletion','leads', ld::text, '00000000-0000-0000-0000-0000000000a1','duplicate') returning id into ar3;
  perform public.decide_approval(ar3, true);
  perform t.eq(t.val(format($q$select (archived_at is not null)::text from public.leads where id=%L$q$, ld)), 'true', 'approved deletion archives (soft) rather than deleting');
  perform public.archive_lead(ld, true);
  perform t.eq(t.val(format($q$select (archived_at is null)::text from public.leads where id=%L$q$, ld)), 'true', 'archive is reversible');
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.eq(t.val($q$select count(*) from public.notifications where type='approval_decided'$q$), '2', 'requester notified of decisions');
  update public.notifications set read_at = now() where read_at is null;
  perform t.denied($q$update public.notifications set title='x'$q$, 'notification content is immutable to users');
end $$;

