\echo === 18. reports and dashboards respect scope
do $$ declare exp_e1 text; exp_all text; exp_m1 text; begin
  select count(*)::text into exp_e1 from public.leads l where owner_id='00000000-0000-0000-0000-0000000000e1' and archived_at is null and stage not in ('won','lost');
  select count(*)::text into exp_all from public.leads l where archived_at is null and stage not in ('won','lost');
  select count(*)::text into exp_m1 from public.leads l where owner_id in ('00000000-0000-0000-0000-0000000000b1','00000000-0000-0000-0000-0000000000e1','00000000-0000-0000-0000-0000000000e2') and archived_at is null and stage not in ('won','lost');
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.eq(t.val($q$select public.dashboard_summary()->>'active_leads'$q$), exp_e1, 'employee dashboard counts only own leads');
  perform t.eq(t.val($q$select count(*) from public.report_by_employee(now()-interval '1 day', now()+interval '1 day')$q$), '1', 'employee report lists only self');
  perform t.act('00000000-0000-0000-0000-0000000000b1');
  perform t.eq(t.val($q$select public.dashboard_summary()->>'active_leads'$q$), exp_m1, 'mentor dashboard counts only team leads');
  perform t.eq(t.val($q$select count(*) from public.report_by_team(now()-interval '1 day', now()+interval '1 day')$q$), '1', 'mentor sees only own team in team report');
  perform t.act('00000000-0000-0000-0000-0000000000a1');
  perform t.eq(t.val($q$select public.dashboard_summary()->>'active_leads'$q$), exp_all, 'admin dashboard counts the company');
  perform t.eq(t.val($q$select public.dashboard_summary(now()-interval '1 day', now()+interval '1 day', 'mine')->>'active_leads'$q$), '0', 'admin personal scope counts only own');
  perform t.eq(t.val($q$select (public.dashboard_summary(now()-interval '1 day', now()+interval '1 day')->>'won')$q$), '1', 'won count from conversions');
  perform t.eq(t.val($q$select (public.dashboard_summary(now()-interval '1 day', now()+interval '1 day')->>'won_value')$q$), '90000.00', 'won value comes from project agreed value, not estimates');
  perform t.eq(t.val($q$select (public.dashboard_summary()->>'pipeline_value')::numeric > 0$q$), 'true', 'pipeline value computed separately');
  perform t.eq(t.val($q$select count(*) from public.report_by_team(now()-interval '1 day', now()+interval '1 day')$q$), '2', 'admin sees all teams');
  perform t.eq(t.val($q$select count(*) > 0 from public.report_lead_sources(now()-interval '1 day', now()+interval '1 day')$q$), 'true', 'lead-source report runs');
  perform t.eq(t.val($q$select count(*) from public.report_monthly_growth(6)$q$), '6', 'monthly growth returns requested months');
  perform t.denied($q$select public.dashboard_summary(now(), now(), 'everything')$q$, 'invalid scope rejected');
  insert into public.user_targets (user_id, period_start, period_end, target_type, target_value)
    values ('00000000-0000-0000-0000-0000000000e1', current_date - 1, current_date + 1, 'conversions', 4);
  perform t.eq(t.val($q$select actual::text || '/' || pct::text from public.target_attainment(current_date, current_date) where target_type='conversions'$q$), '1/25.0', 'target attainment actual vs target');
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.eq(t.val('select count(*) from public.target_attainment(current_date, current_date)'), '1', 'employee sees own target');
  perform t.act('00000000-0000-0000-0000-0000000000e2');
  perform t.eq(t.val('select count(*) from public.target_attainment(current_date, current_date)'), '0', 'other employee cannot');
  perform t.denied($q$insert into public.user_targets (user_id, period_start, period_end, target_type, target_value) values ('00000000-0000-0000-0000-0000000000e2', current_date, current_date, 'outreach', 1)$q$, 'employee cannot set own targets');
  perform t.act('00000000-0000-0000-0000-0000000000e1');
  perform t.eq(t.val($q$select count(*) from public.my_action_items()$q$), '0', 'nothing due yet: future follow-ups are not listed');
  insert into public.tasks (title, assigned_to, due_at) values ('Overdue thing','00000000-0000-0000-0000-0000000000e1', now() - interval '2 days');
  perform t.eq(t.val($q$select kind || ':' || is_overdue::text from public.my_action_items()$q$), 'task:true', 'overdue task surfaces in the action centre');
  perform t.eq(t.val($q$select (public.dashboard_summary(now()-interval '1 day', now()+interval '1 day','mine')->>'overdue_tasks')$q$), '1', 'dashboard overdue-task count matches');
end $$;

\echo === 19. admin guard rails
do $$ begin
  perform t.denied($q$update public.profiles set is_active = false where id = '00000000-0000-0000-0000-0000000000a1'$q$, 'last active admin cannot be deactivated');
  perform t.denied($q$update public.profiles set role = 'mentor' where id = '00000000-0000-0000-0000-0000000000a1'$q$, 'last admin cannot be demoted');
  perform t.denied($q$delete from public.profiles where id = '00000000-0000-0000-0000-0000000000a1'$q$, 'last admin cannot be deleted');
  perform t.denied($q$delete from public.pipeline_stages where key = 'new'$q$, 'stages in use cannot be deleted', array['23503']);
  perform t.denied($q$update public.pipeline_stages set is_won = true where key = 'new'$q$, 'only one Won stage allowed', array['23505']);
end $$;
do $$ begin perform t.act('00000000-0000-0000-0000-0000000000a1');
  perform public.admin_update_profile('00000000-0000-0000-0000-0000000000e2', 'mentor', null, 'Eli Promoted');
  perform t.eq(t.val($q$select role from public.profiles where id='00000000-0000-0000-0000-0000000000e2'$q$), 'mentor', 'admin changes a role');
  perform t.eq(t.val($q$select count(*) from public.audit_logs where entity_type='profiles' and entity_id='00000000-0000-0000-0000-0000000000e2' and after_data->>'role'='mentor' and before_data->>'role'='bds_employee'$q$), '1', 'role change audited with before/after and actor');
  perform t.eq(t.val($q$select actor_id::text from public.audit_logs where entity_type='profiles' and entity_id='00000000-0000-0000-0000-0000000000e2' and after_data->>'role'='mentor' order by id desc limit 1$q$), '00000000-0000-0000-0000-0000000000a1', 'audit records the acting admin');
  perform public.admin_update_profile('00000000-0000-0000-0000-0000000000e2', 'bds_employee');
end $$;
